        await saveTask(ctx, updatedTask);
        await syncSpecImplementationStatus(ctx, updatedTask, tasks, items, index);
        await commitIfShadow(ctx.shadow, `task: submit ${params.ref}`);

        pubsub.broadcast('tasks:updates', 'task_updated', {
